package com.loopers.domain.payment
import com.loopers.domain.BaseEntity;import com.loopers.support.error.*;import jakarta.persistence.*
// Hides: payment uncertainty transitions, provider identifiers, and terminal-state monotonicity.
@Entity @Table(name="payment_intent",uniqueConstraints=[UniqueConstraint(columnNames=["internalOrderId","paymentAttemptKey"]),UniqueConstraint(columnNames=["providerOrderId"])]) class PaymentIntent(val internalOrderId:Long,val paymentAttemptKey:String,val amount:Long):BaseEntity(){enum class Status{READY,REQUESTED,UNKNOWN,CONFIRMED,FAILED};val providerOrderId="LP-ORD-%010d".format(internalOrderId);var pgTransactionId:String?=null;protected set;@Enumerated(EnumType.STRING)var status=Status.READY;protected set;init{if(internalOrderId<=0||paymentAttemptKey.isBlank()||amount<0)throw CoreException(ErrorType.BAD_REQUEST)};fun requested(){if(status==Status.READY)status=Status.REQUESTED};fun unknown(){if(status==Status.REQUESTED)status=Status.UNKNOWN};fun settle(tx:String,next:Status){if(next!=Status.CONFIRMED&&next!=Status.FAILED)throw CoreException(ErrorType.BAD_REQUEST);if(status==Status.CONFIRMED||status==Status.FAILED)return;pgTransactionId=tx;status=next}}
